def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Returns True if any two numbers in the given list are closer to each other than the given threshold.
    """
    for i in range(len(numbers)):
        for j in range(i+1, len(numbers)):
            if abs(numbers[i] - numbers[j]) <= threshold:
                return True
    return False

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the dynamic programming table
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # Populate the dynamic programming table
    for i in range(N):
        for j in range(N):
            value = grid_values[i][j]
            dp[i][j] = max(dp[i - 1][j - 1], dp[i - 1][j]) + value

    # Return the maximum value in the last row of the dynamic programming table
    return max(dp[-1])

